const FAVICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="#10b981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/></svg>`;

// --- Default CORS Headers Helper ---
function getCorsHeaders(request) {
  const origin = request.headers.get('Origin') || '*';
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With, User-Agent',
    'Access-Control-Allow-Credentials': 'true',
  };
}

function jsonResponse(data, status = 200, request = null) {
  const corsHeaders = request ? getCorsHeaders(request) : { 'Access-Control-Allow-Origin': '*' };
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...corsHeaders,
    },
  });
}

function errorResponse(message, status = 400, request = null) {
  return jsonResponse({ success: false, message }, status, request);
}

// --- SQL Schema Initialization Script ---
const INITIAL_SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS admin_config (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password TEXT,
  role TEXT DEFAULT 'user',
  status TEXT DEFAULT 'active',
  expire_date TEXT,
  order_index INTEGER DEFAULT 1,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS links (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  title TEXT NOT NULL,
  url TEXT NOT NULL,
  order_index INTEGER DEFAULT 1,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);
`;

// Seed initial admin credentials only if database is empty (no fake users)
async function initializeDatabaseIfNeeded(db) {
  try {
    const statements = INITIAL_SCHEMA_SQL.split(';')
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

    for (const sql of statements) {
      await db.prepare(sql).run();
    }

    // Auto-migrate order_index column if it does not exist
    try { await db.prepare("ALTER TABLE users ADD COLUMN order_index INTEGER DEFAULT 1").run(); } catch (e) {}
    try { await db.prepare("ALTER TABLE links ADD COLUMN order_index INTEGER DEFAULT 1").run(); } catch (e) {}

    const adminCheck = await db.prepare("SELECT value FROM admin_config WHERE key = 'admin_username'").first();
    if (!adminCheck) {
      await db.batch([
        db.prepare("INSERT OR REPLACE INTO admin_config (key, value) VALUES ('admin_username', 'admin')"),
        db.prepare("INSERT OR REPLACE INTO admin_config (key, value) VALUES ('admin_password_hash', '123456')"),
      ]);
    }
  } catch (err) {
    console.error('Database Initialization Error:', err);
  }
}

// Check User-Agent for VPN clients
function isVpnClient(userAgent = '') {
  const ua = userAgent.toLowerCase();
  const clientKeywords = [
    'v2ray',
    'v2rayng',
    'nekobox',
    'shadowrocket',
    'hiddify',
    'streisand',
    'sing-box',
    'clash',
    'stash',
    'quantumult',
    'curl',
    'wget',
    'python',
    'go-http-client',
  ];
  return clientKeywords.some((k) => ua.includes(k));
}

// Convert string to Base64
function toBase64(str) {
  const bytes = new TextEncoder().encode(str);
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

// Format Unix Timestamp
function getUnixTimestamp(dateString) {
  if (!dateString) return 0;
  return Math.floor(new Date(dateString).getTime() / 1000);
}

